"""cedar_independent_measurement_round_1.py

A small pure-function library for invoice validation, event sorting, and
amount summarization. All functions are side-effect free and operate only
on their arguments.
"""

from __future__ import annotations

from typing import Any, Iterable, Mapping, Sequence


def is_mapping(value: Any) -> bool:
    """Return True if value is a mapping-like object."""
    return isinstance(value, Mapping)


def is_sequence(value: Any) -> bool:
    """Return True if value is a non-string sequence."""
    return isinstance(value, Sequence) and not isinstance(value, (str, bytes))


def invoice_is_dict(invoice: Any) -> bool:
    """Return True if invoice is a dictionary."""
    return isinstance(invoice, dict)


def invoice_has_id(invoice: Mapping[str, Any]) -> bool:
    """Return True if invoice contains a non-empty string id."""
    value = invoice.get("id")
    return isinstance(value, str) and value.strip() != ""


def invoice_has_customer(invoice: Mapping[str, Any]) -> bool:
    """Return True if invoice contains a non-empty customer name."""
    value = invoice.get("customer")
    return isinstance(value, str) and value.strip() != ""


def invoice_has_date(invoice: Mapping[str, Any]) -> bool:
    """Return True if invoice contains a non-empty date string."""
    value = invoice.get("date")
    return isinstance(value, str) and value.strip() != ""


def invoice_has_items(invoice: Mapping[str, Any]) -> bool:
    """Return True if invoice contains a non-empty items list."""
    value = invoice.get("items")
    return is_sequence(value) and len(value) > 0


def invoice_has_currency(invoice: Mapping[str, Any]) -> bool:
    """Return True if invoice contains a non-empty currency string."""
    value = invoice.get("currency")
    return isinstance(value, str) and value.strip() != ""


def invoice_has_total(invoice: Mapping[str, Any]) -> bool:
    """Return True if invoice contains a numeric total."""
    value = invoice.get("total")
    return isinstance(value, (int, float)) and not isinstance(value, bool)


